ue is selected. Ties are broken randomly.\n\n    Args:\n        state: The current environment observation (np.ndarray of shape (9,) with dtype int8).\n               Must contain only values from {-1, 0, 1}.\n\n    Returns:\n        action: An integer in [0, 8] representing the chosen cell index.\n    \"\"\"\n        if self.rng.random() < self.epsilon:\n            return self.rng.integers(0, self.env.action_space.n)\n        actions = np.array([self.q_table[state][i] for i in range(self.env.action_space.n)], dtype=np.float64)\n        best_action_indices = np.argsort(actions)[::-1][:]\n        if len(best_action_indices) == 0:\n            return 0\n        best_values = actions[best_action_indices[0]]\n        top_indices = [i for i, val in enumerate(actions) if abs(val - best_values) < 1e-06]\n        chosen_index = self.rng.choice(top_indices)\n        return int(best_action_indices[chosen_index])\n\n    def update(self, state: np.ndarray, action: int, reward: float, next_state: np.ndarray, done: bool) -> None:\n        \"\"\"Update the Q-value for the given state-action pair.\n\n    Uses the standard Q-Learning update rule:\n    Q(s, a) <- Q(s, a) + alpha * (reward + gamma * max_a' Q(s', a') - Q(s, a))\n\n    Args:\n        state: The previous environment observation.\n        action: The action taken by the agent.\n        reward: The reward received from the environment.\n        next_state: The new environment observation after taking the action.\n        done: Boolean indicating if the episode has terminated.\n    \"\"\"\n        current_q = self.q_table[state][action]\n        if done:\n            max_next_q = 0.0\n        else:\n            max_next_q = np.max(self.q_table[next_state])\n        new_q = current_q + self.alpha * (reward + self.gamma * max_next_q - current_q)\n        self.q_table[state][action] = float(new_q)\n",
